/* Browser adapter: local persistence, inspection UI, and one shared Canvas renderer. */
(()=>{
const {Simulation,spots,recipes}=VillageEngine,KEY='vishnu-village-v1';let sim,storageOK=true;
try{const raw=localStorage.getItem(KEY);sim=new Simulation(raw?JSON.parse(raw):null)}catch{sim=new Simulation();storageOK=false}
let selected='a0',hub='map',paused=false,speed=1,elapsed=0,last=performance.now(),lastUI=0;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stateNames={build:'Building',idle:'Idle',walk:'Walking',gather:'Gathering',craft:'Crafting',chat:'Talking',eat:'Eating',rest:'Resting',offer:'Offering food'};
function save(){try{localStorage.setItem(KEY,JSON.stringify(sim.snapshot()));storageOK=true}catch{storageOK=false}}
function time(t){return `${Math.floor(t/60)}m ${t%60}s`}
function mount(){const route=location.hash.replace(/^#\/?/,'').split('/')[0];if(route===''||route==='play'){const hill=document.querySelector('.hill');if(hill){hill.outerHTML=`<section class="live-hill"><canvas class="game-scene" data-scene="hill" aria-label="Five residents on the homepage hill"></canvas><div class="hill-caption"><span>Homepage hill · up to five residents</span><a href="#/village">Enter the village →</a></div></section>`}}
if(route==='village'){hub='map';document.querySelector('main').innerHTML=`<div class="pageheading"><h1>The village</h1><p>A small, living economy. Click a resident to follow their story.</p><a class="button primary" href="lab.html">Open the Society lab →</a></div><div class="sim-toolbar"><label>Time <select id="sim-speed"><option value="1">1×</option><option value="5">5×</option><option value="20">20×</option></select></label><button class="button" id="sim-pause">${paused?'Resume':'Pause'}</button><button class="button" id="sim-step">Step 5 seconds</button><strong id="sim-clock"></strong><span class="spacer"></span><button class="button" id="sim-expand">Expand scene ↗</button><button class="button" id="sim-reset">Reset world</button></div><div class="hub-nav" aria-label="Village locations">${[['hill','Homepage hill'],['garden','Garden'],['workshop','Workshops'],['pond','Pond'],['homes','Homes'],['elements','Elemental sources'],['map','World map']].map(([id,n])=>`<button class="button ${hub===id?'primary':''}" data-hub="${id}">${n}</button>`).join('')}</div><div class="sim-layout"><section class="panel sim-stage" id="sim-stage"><h2 class="panelhead blue" id="hub-title"></h2><div class="scene-wrap"><canvas class="game-scene" data-scene="current" tabindex="0" aria-label="Village scene. Select residents using the list below."></canvas><div id="map-destinations"></div></div><div id="world-summary"></div><div id="hub-infrastructure"></div><div class="resident-list" id="resident-list"></div><p class="scene-help" id="scene-help"></p><button class="button sim-close" id="sim-close">Close expanded scene ×</button></section><aside class="panel"><h2 class="panelhead green">Resident inspector</h2><div class="panelbody" id="resident-inspector"></div></aside></div><div class="sim-bottom"><section class="panel"><h2 class="panelhead yellow">Agreements &amp; goods</h2><div class="panelbody"><div class="contract-controls"><label>Other resident <select id="other-agent">${sim.s.agents.filter(a=>a.id!==selected).map(a=>`<option value="${a.id}">${a.name}</option>`).join('')}</select></label><label>Request <select id="contract-kind"><option value="gift">Offer 2 food</option><option value="hat">Commission hat · 3 food</option><option value="stool">Commission stool · 3 food</option><option value="pot">Commission pot · 3 food</option><option value="meet">Arrange a meetup</option><option value="loan">Lend first owned item · 60s</option><option value="sale">Offer first owned item · 3 food</option></select></label><button class="button primary" id="propose-contract">Propose agreement</button></div><p class="small-copy">Proposals may be declined. Commissions hold payment in escrow; ownership transfers on completion. Food is the current barter convention.</p><div id="contract-feedback" role="status"></div><div class="sim-tabs"><button class="button primary" data-ledger="contracts">Contracts</button><button class="button" data-ledger="goods">Goods &amp; ownership</button><button class="button" data-ledger="production">Production</button></div><div id="sim-ledger"></div></div></section><section class="panel"><h2 class="panelhead blue">Village log</h2><div class="panelbody"><p class="small-copy">Decisions and outcomes, newest first.</p><ol id="sim-log" class="sim-log"></ol></div></section></div><p class="preview-note" id="save-status"></p><dialog id="reset-dialog"><h2>Start this local world over?</h2><p>This replaces the simulation saved in this browser. It does not affect anyone else.</p><button class="button" id="reset-cancel">Keep world</button> <button class="button primary" id="reset-confirm">Reset local world</button></dialog>`;wire();update(true)}
if(route==='play'){const p=document.querySelector('.preview-note');if(p)p.textContent='The village is a working local simulation. The creature drawing editor is still a layout preview.'}document.querySelectorAll('.game-scene').forEach(canvas=>canvas.onclick=e=>{const rect=canvas.getBoundingClientRect(),scale=Math.min(rect.width/900,rect.height/360),x=(e.clientX-rect.left-(rect.width-900*scale)/2)/scale,y=(e.clientY-rect.top-(rect.height-360*scale)/2)/scale;const scene=canvas.dataset.scene==='hill'?'hill':hub;if(scene==='map')return;const residents=sim.s.agents.filter(a=>a.hub===scene);const a=residents.find(a=>{const pos=position(a,scene);return Math.abs(pos.x-x)<45&&Math.abs(pos.y-45-y)<70});if(a){selected=a.id;if(canvas.dataset.scene==='hill'){hub='hill';location.hash='/village'}else update(true)}});
// Old preview text no longer describes the live engine.
document.querySelector('#notice p').textContent='The village is a working local prototype: needs, relationships, crafting and contracts run in this browser and save here. It is not a shared server world yet. The drawing editor remains a layout preview.';
}
let ledger='contracts';
function setHub(h){hub=h;document.querySelectorAll('[data-hub]').forEach(b=>b.classList.toggle('primary',b.dataset.hub===h));update(true)}
function wire(){document.querySelector('#sim-speed').value=String(speed);document.querySelector('#sim-speed').onchange=e=>speed=Number(e.target.value);document.querySelector('#sim-pause').onclick=e=>{paused=!paused;e.target.textContent=paused?'Resume':'Pause'};document.querySelector('#sim-step').onclick=()=>{sim.tick();elapsed=0;save();update(true)};document.querySelectorAll('[data-hub]').forEach(b=>b.onclick=()=>setHub(b.dataset.hub));document.querySelector('#sim-expand').onclick=()=>{document.querySelector('#sim-stage').classList.add('sim-expanded');document.body.style.overflow='hidden';document.querySelector('#sim-close').focus()};document.querySelector('#sim-close').onclick=closeExpand;document.querySelector('#sim-reset').onclick=()=>document.querySelector('#reset-dialog').showModal();document.querySelector('#reset-cancel').onclick=()=>document.querySelector('#reset-dialog').close();document.querySelector('#reset-confirm').onclick=()=>{sim=new Simulation();elapsed=0;save();document.querySelector('#reset-dialog').close();update(true)};
document.querySelector('#propose-contract').onclick=()=>{const kind=document.querySelector('#contract-kind').value,to=document.querySelector('#other-agent').value;let type=kind,terms={};if(['hat','stool','pot'].includes(kind)){type='commission';terms={recipe:kind,price:3}}else if(kind==='gift')terms={amount:2};else if(['loan','sale'].includes(kind)){const item=sim.s.items.find(i=>i.owners.length===1&&i.owners[0]===selected&&i.holder===selected);if(!item){document.querySelector('#contract-feedback').textContent='This resident has no available privately owned item.';return}terms={item:item.id,price:3}}const c=sim.propose(type,selected,to,terms);document.querySelector('#contract-feedback').textContent=`${c.id} proposed. The other resident will decide on the next tick.`;save();update(true)};document.querySelectorAll('[data-ledger]').forEach(b=>b.onclick=()=>{ledger=b.dataset.ledger;document.querySelectorAll('[data-ledger]').forEach(x=>x.classList.toggle('primary',x===b));update(true)})}
const destinations=[['hill','Homepage hill',22,22],['garden','Garden',42,69],['workshop','Workshops',61,37],['pond','Pond',10,68],['homes','Homes',82,39],['elements','Elemental sources',86,80]];
function updateWorld(){const overview=hub==='map';document.querySelector('.sim-layout').classList.toggle('overview',overview);const markers=document.querySelector('#map-destinations');markers.hidden=!overview;markers.innerHTML=overview?destinations.map(([id,label,x,y])=>'<button class="map-destination" data-enter="'+id+'" style="left:'+x+'%;top:'+y+'%">'+label+'<small>'+sim.s.agents.filter(a=>a.hub===id).length+' residents</small></button>').join(''):'';markers.querySelectorAll('button').forEach(b=>b.onclick=()=>setHub(b.dataset.enter));document.querySelector('#world-summary').innerHTML=overview?'<div class="world-stats"><span><strong>'+sim.s.agents.length+'</strong> residents</span><span><strong>'+sim.s.agents.filter(a=>a.action?.type==='craft').length+'</strong> making things</span><span><strong>'+sim.s.contracts.filter(c=>c.status==='active').length+'</strong> active agreements</span><span><strong>'+Math.floor(sim.s.resources.food)+'</strong> shared food</span></div><p class="small-copy world-hint">Choose a location to enter its hub. Facilities are already built for this demo; each hub can expand.</p>':'';const infrastructure=document.querySelector('#hub-infrastructure');infrastructure.innerHTML=overview||hub==='hill'?'':'<div class="infrastructure"><span>'+sim.s.infrastructure[hub]+' '+({homes:'homes',workshop:'workshop blocks',garden:'growing plots',pond:'water access points',elements:'gathering sites'}[hub])+'</span><button class="button small" id="expand-infrastructure">Build another · 6 timber + 4 food</button><span id="build-feedback" role="status"></span></div>';document.querySelector('#expand-infrastructure')?.addEventListener('click',()=>{const a=sim.agent(selected);const ok=sim.build(a,hub);document.querySelector('#build-feedback').textContent=ok?a.name+' is building.':'Choose a resident with 6 timber and 4 food, available to build.';save()})}
function closeExpand(){document.querySelector('#sim-stage')?.classList.remove('sim-expanded');document.body.style.overflow='';document.querySelector('#sim-expand')?.focus()}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeExpand()});
function update(force=false){if(!document.querySelector('#resident-inspector'))return;const a=sim.agent(selected),act=a.action;updateWorld();document.querySelector('#sim-clock').textContent=`World time ${time(sim.s.time)}`;document.querySelector('#hub-title').textContent=hub==='map'?'World map — choose a location':spots[hub].name;document.querySelector('#scene-help').textContent=hub==='map'?'Click the map or use the location buttons to enter a hub.':'Click a creature, or choose a name below. Actions use the same simulation in every location.';
document.querySelector('#resident-list').innerHTML=(hub==='map'?sim.s.agents:sim.s.agents.filter(a=>a.hub===hub)).map(a=>`<button class="button small ${a.id===selected?'primary':''}" data-resident="${a.id}">${a.name} · ${stateNames[a.action?.type]||'Idle'}</button>`).join('')||'<span class="muted">Nobody here right now. The world is still running.</span>';document.querySelectorAll('[data-resident]').forEach(b=>b.onclick=()=>{selected=b.dataset.resident;update(true)});
const openDetails=[...document.querySelectorAll('#resident-inspector details[open]')].map(d=>d.querySelector('summary').textContent);const inventory=Object.entries(a.inventory).filter(([,n])=>n).map(([k,n])=>`${n} ${k}`).join(', ')||'Nothing carried';const own=sim.s.items.filter(i=>i.owners.includes(a.id));
document.querySelector('#resident-inspector').innerHTML=`<h3>${a.name} <span class="sample">${spots[a.hub].name}</span></h3><p class="why"><strong>${stateNames[act?.type]||'Idle'}</strong><br>${esc(a.reason)}${act?`<br><small>${Math.max(0,act.end-sim.s.time)}s remaining</small>`:''}</p><div class="needs">${Object.entries(a.needs).map(([k,v])=>`<div class="needrow"><span>${k}</span><div class="bar"><i style="width:${v}%;background:${v>70?'#dd8c6b':'#92bb65'}"></i></div><small>${Math.round(v)}</small></div>`).join('')}</div><p class="small-copy">Higher bars = stronger unmet needs. Nobody dies.</p><h3>Carrying</h3><p class="small-copy">${inventory}</p><p class="small-copy">Owned goods: ${own.map(i=>`${i.color} ${i.type}`).join(', ')||'none'}</p><details><summary>Personality &amp; taste</summary><p class="small-copy">${Object.entries(a.traits).map(([k,v])=>`${k}: ${v}`).join(' · ')}<br>Likes ${a.taste.color}; crafting experience ${Math.round(a.skill)}.</p></details><details><summary>Relationships</summary>${Object.entries(a.relations).map(([id,r])=>`<p class="small-copy">${sim.agent(id).name}: trust ${Math.round(r.trust)}, affection ${Math.round(r.affection)}, familiarity ${Math.round(r.familiarity)}</p>`).join('')}</details><button class="button small" id="follow-resident">Go to ${a.name} →</button><button class="button small" id="repair-bench">Repair workbench · 1 timber</button>`;
document.querySelectorAll('#resident-inspector details').forEach(d=>d.open=openDetails.includes(d.querySelector('summary').textContent));document.querySelector('#follow-resident').onclick=()=>setHub(a.hub);document.querySelector('#repair-bench').onclick=()=>{document.querySelector('#contract-feedback').textContent=sim.repair(a)?'Workbench repaired.':'Needs one timber and must be idle. Pause, step to a new action, or try another resident.';save();update(true)};
if(force){const other=document.querySelector('#other-agent'),old=other.value;other.innerHTML=sim.s.agents.filter(b=>b.id!==selected).map(b=>`<option value="${b.id}">${b.name}</option>`).join('');if(old&&old!==selected)other.value=old}
const target=document.querySelector('#sim-ledger');if(ledger==='contracts')target.innerHTML=sim.s.contracts.length?`<div class="table-scroll"><table class="ledger"><thead><tr><th>Agreement</th><th>Parties</th><th>Status</th></tr></thead><tbody>${sim.s.contracts.slice(0,18).map(c=>`<tr><td>${c.id} · ${c.type}${c.terms.recipe?' / '+c.terms.recipe:''}${c.terms.price!==undefined?'<br>'+c.terms.price+' food':''}</td><td>${sim.agent(c.from).name} → ${sim.agent(c.to).name}</td><td><span class="contract-status ${c.status}">${c.status}</span>${c.note?'<br>'+esc(c.note):''}${c.escrow?'<br>'+c.escrow+' food in escrow':''}</td></tr>`).join('')}</tbody></table></div>`:'<p>No agreements yet. Propose one above, or watch residents interact.</p>';
else if(ledger==='goods')target.innerHTML=`<div class="table-scroll"><table class="ledger"><thead><tr><th>Good</th><th>Owner / holder</th><th>Condition</th></tr></thead><tbody>${sim.s.items.map(i=>`<tr><td>${i.color} ${i.type}<br><small>${i.quality}</small></td><td>${i.owners.map(id=>id==='community'?'Community':sim.agent(id).name).join(', ')} / ${i.holder?sim.agent(i.holder).name:'public access'}</td><td>${Math.round(i.condition)}%</td></tr>`).join('')}</tbody></table></div>`;
else target.innerHTML=`<p class="small-copy">Earth: clay &amp; growth · Water: processing · Air: replenishes stored energy · Fire: kiln energy use. Elemental recipes are an early abstraction.</p><div class="resource-chips">${Object.entries(sim.s.resources).map(([k,n])=>`<span>${k}: ${Math.floor(n)}</span>`).join('')}</div>${Object.entries(recipes).map(([k,r])=>`<p class="small-copy"><strong>${k}</strong>: ${Object.entries(r.inputs).map(([k,n])=>n+' '+k).join(' + ')} · ${r.duration}s · ${r.station} (${Math.round(sim.s.stations[r.station].condition)}% condition)</p>`).join('')}<p class="sample">Shared sources replenish slowly. Work spots allow one job at a time. Hats are bought for taste and novelty, not survival.</p>`;
document.querySelector('#sim-log').innerHTML=sim.s.events.slice(0,18).map(e=>`<li><time>${time(e.time)}</time> ${esc(e.text)}</li>`).join('');document.querySelector('#save-status').textContent=storageOK?'Local prototype · saved in this browser · no shared server or offline progression yet. Creator drawing remains a separate layout preview.':'Local prototype · browser storage unavailable; this world will last only for this tab.';
}
function position(a,scene){const act=a.action,progress=act?Math.min(1,(sim.s.time+elapsed-act.start)/(act.end-act.start)):1;const travel=act?Math.min(1,(sim.s.time+elapsed-act.start)/10):1;const x=act&&['walk','gather','craft'].includes(act.type)?act.fromX+(act.toX-act.fromX)*travel:a.x;return{x,y:scene==='hill'?290:278+(sim.s.agents.indexOf(a)%2)*24}}
function cloud(c,x,y,s){c.fillStyle='#fffdf3';c.beginPath();c.ellipse(x,y,35*s,12*s,0,0,7);c.ellipse(x-12*s,y-8*s,15*s,14*s,0,0,7);c.ellipse(x+10*s,y-12*s,20*s,18*s,0,0,7);c.fill()}
function scene(c,place,t){c.clearRect(0,0,900,360);c.fillStyle='#b7e7f9';c.fillRect(0,0,900,360);cloud(c,170,65,1);cloud(c,620,38,.65);c.fillStyle='#b5dd78';c.beginPath();c.moveTo(-10000,220);c.lineTo(0,220);c.quadraticCurveTo(210,130,420,210);c.quadraticCurveTo(650,125,900,200);c.lineTo(10000,200);c.lineTo(10000,360);c.lineTo(-10000,360);c.fill();c.strokeStyle='#49623a';c.lineWidth=2;c.beginPath();c.moveTo(-10000,260);c.lineTo(0,260);c.quadraticCurveTo(400,205,900,255);c.lineTo(10000,255);c.stroke();c.fillStyle='#92ce63';c.beginPath();c.moveTo(-10000,260);c.lineTo(0,260);c.quadraticCurveTo(400,205,900,255);c.lineTo(10000,255);c.lineTo(10000,360);c.lineTo(-10000,360);c.fill();
if(place==='hill'){mushroom(c,795,267,.9);c.strokeStyle='#573f29';c.lineWidth=6;c.beginPath();c.moveTo(380,261);c.lineTo(510,261);c.moveTo(390,245);c.lineTo(500,245);c.moveTo(395,265);c.lineTo(390,291);c.moveTo(500,265);c.lineTo(508,291);c.stroke()}
if(place==='pond'){c.fillStyle='#4fc0ed';c.strokeStyle='#4486ad';c.lineWidth=2;c.beginPath();c.ellipse(470,245,215,65,0,0,7);c.fill();c.stroke();c.strokeStyle='#d8f5ff';for(let i=0;i<5;i++){c.beginPath();c.moveTo(320+i*65,240+i%2*15);c.lineTo(345+i*65,240+i%2*15);c.stroke()}}
if(place==='garden'){c.fillStyle='#c29960';c.fillRect(220,180,390,100);for(let i=0;i<12;i++){const x=245+i%6*65,y=205+Math.floor(i/6)*48;c.fillStyle='#4c963d';c.beginPath();c.ellipse(x,y,20,16,0,0,7);c.fill();c.fillStyle='#dc5144';c.beginPath();c.arc(x+4,y-2,5,0,7);c.fill()}c.strokeStyle='#795129';c.lineWidth=4;c.strokeRect(210,175,410,110)}
if(place==='workshop'){mushroom(c,760,245,.7);c.fillStyle='#ad7b43';c.strokeStyle='#4e3f32';for(let i=0;i<4;i++){const x=120+i*165;c.fillRect(x,210,105,15);c.strokeRect(x,210,105,15);c.fillRect(x+8,225,7,35);c.fillRect(x+90,225,7,35);c.font='18px Patrick';c.fillStyle='#173750';c.fillText(['Loom','Tailor','Workbench','Kiln'][i],x,195);c.fillStyle='#ad7b43'}}
c.strokeStyle='#518342';c.lineWidth=1.5;for(let i=0;i<25;i++){const x=(i*137)%900,y=325+(i%3)*12;c.beginPath();c.moveTo(x-3,y-6);c.lineTo(x,y);c.lineTo(x+4,y-8);c.stroke()}}
const mapImage=new Image();mapImage.src='assets/village.png';
function mushroom(c,x,y,size=1){CreatureArt.house(c,x,y+10,140*size)}
function creature(c,a,pos,t){let action=a.action?.type||'idle';if(['craft','gather'].includes(action)&&sim.s.time+elapsed-a.action.start<8)action='walk';CreatureArt.sprite(c,a.kind,pos.x,pos.y,112,action,paused?0:t,Number(a.id.slice(1)));const hat=sim.s.items.find(i=>i.type==='hat'&&i.holder===a.id);if(hat){c.save();c.fillStyle={green:'#4d9844',blue:'#466ab7',purple:'#a064b5'}[hat.color]||'#c55e43';c.strokeStyle='#25332a';c.beginPath();c.moveTo(pos.x-18,pos.y-108);c.lineTo(pos.x-10,pos.y-127);c.lineTo(pos.x+12,pos.y-125);c.lineTo(pos.x+20,pos.y-108);c.closePath();c.fill();c.stroke();c.restore()}c.fillStyle='#163550';c.font='16px Patrick';c.textAlign='center';c.fillText(a.name,pos.x,pos.y+20);if(a.id===selected&&location.hash.includes('village')){c.strokeStyle='#f0bf43';c.lineWidth=2;c.beginPath();c.ellipse(pos.x,pos.y+2,25,5,0,0,7);c.stroke()}}
function draw(now){document.querySelectorAll('.game-scene').forEach(canvas=>{const r=canvas.getBoundingClientRect();if(r.bottom<0||r.top>innerHeight)return;const dpr=Math.min(devicePixelRatio||1,2),w=Math.round(r.width*dpr),h=Math.round(r.height*dpr);if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h}const c=canvas.getContext('2d');c.setTransform(1,0,0,1,0,0);c.fillStyle='#b7e7f9';c.fillRect(0,0,w,h);c.fillStyle='#92ce63';c.fillRect(0,h*.74,w,h*.26);const scale=Math.min(w/900,h/360);c.setTransform(scale,0,0,scale,(w-900*scale)/2,(h-360*scale)/2);const place=canvas.dataset.scene==='hill'?'hill':hub;if(place==='map'){if(mapImage.complete&&mapImage.naturalWidth){const mh=900*mapImage.height/mapImage.width;c.drawImage(mapImage,0,(360-mh)/2,900,mh)}return}scene(c,place,now/1000);if(place==='homes'){for(let i=0;i<Math.min(7,sim.s.infrastructure.homes);i++)CreatureArt.house(c,145+i*100,245,115)}if(place==='elements'){c.fillStyle='#bba37c';for(let i=0;i<5;i++){c.beginPath();c.ellipse(160+i*35,245-i%2*17,27,23,.2,0,7);c.fill()}c.fillStyle='#8ccae0';c.fillRect(400,200,65,50);c.fillStyle='#dca65e';c.fillRect(610,180,60,70);c.font='19px Patrick';c.fillStyle='#183853';c.fillText('Earth',180,174);c.fillText('Water',430,174);c.fillText('Air / fire energy',660,160)}sim.s.agents.filter(a=>a.hub===place).sort((a,b)=>position(a,place).y-position(b,place).y).forEach(a=>creature(c,a,position(a,place),now/1000));})}
function frame(now){const dt=Math.min((now-last)/1000,.25);last=now;if(!paused&&!document.hidden){elapsed+=dt*speed;let ticks=0;while(elapsed>=5&&ticks++<10){elapsed-=5;sim.tick();save()}if(ticks)update()}draw(now);if(now-lastUI>1500){lastUI=now;update()}requestAnimationFrame(frame)}
// app.js owns ordinary page navigation; mounting runs after its render listener.
window.addEventListener('hashchange',mount);document.addEventListener('visibilitychange',()=>{last=performance.now();save()});window.addEventListener('pagehide',save);mount();requestAnimationFrame(frame);
})();




